onRoleReachedMoon = function()     game.pauseLogic()	if global.getBool("lvl48_b1") then dialog.setSkipEnabled(true) end		repeat			sound.play("51-2");		    if dialog.show("Level48-1", faceBujie) ==1 then break end			if dialog.show("Level48-2", faceZhoumei) ==1 then break end			if dialog.show("Level48-3", faceWunai) ==1 then break end			if dialog.show("Level48-4", facePutong) ==1 then break end			sound.play("50-1");		    if dialog.show("Level48-5", facePutong) ==1 then break end			if dialog.show("Level48-6", faceZhoumei) ==1 then break end			if dialog.show("Level48-7", facePutong) ==1 then break end			sound.play("60-2");			if dialog.show("Level48-8", faceBujie) ==1 then break end			global.setBool("lvl48_b1")		until true		dialog.setSkipEnabled(false)    game.success()end